def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    me = []
    op = []
    for a, b in history:
        if a == 'C':
            me.append(0)
        else:
            me.append(1)
        if b == 'C':
            op.append(0)
        else:
            op.append(1)

    last_me = me[-1]
    last_op = op[-1]

    opp_c = 0
    for x in op:
        if x == 0:
            opp_c += 1
    opp_rate = opp_c / float(n)

    if n == 1:
        if last_op == 1:
            return 'D'
        return 'C'

    if n <= 3 and opp_c == 0:
        return 'D'

    run_op_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 1:
            run_op_d += 1
        else:
            break

    run_op_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 0:
            run_op_c += 1
        else:
            break

    run_me_d = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 1:
            run_me_d += 1
        else:
            break

    run_me_c = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 0:
            run_me_c += 1
        else:
            break

    dc_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 1 and op[i] == 0:
            dc_streak += 1
        else:
            break

    cc_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 0 and op[i] == 0:
            cc_streak += 1
        else:
            break

    our_c_in_run = 0
    if run_op_d > 0:
        start = n - run_op_d
        for i in range(start, n):
            if me[i] == 0:
                our_c_in_run += 1

    rec8 = min(8, n)
    rec12 = min(12, n)
    recent_op_c = 0
    for i in range(n - rec8, n):
        if op[i] == 0:
            recent_op_c += 1

    recent_cd = 0
    recent_dc = 0
    for i in range(n - rec12, n):
        if me[i] == 0 and op[i] == 1:
            recent_cd += 1
        elif me[i] == 1 and op[i] == 0:
            recent_dc += 1

    resp_myD_c = 0
    resp_myD_d = 0
    resp_myC_c = 0
    resp_myC_d = 0
    for i in range(n - 1):
        if me[i] == 0:
            if op[i + 1] == 0:
                resp_myC_c += 1
            else:
                resp_myC_d += 1
        else:
            if op[i + 1] == 0:
                resp_myD_c += 1
            else:
                resp_myD_d += 1

    win = min(20, n)
    unprovoked_d_runs = 0
    for i in range(n - win, n):
        if op[i] == 1 and (i == 0 or op[i - 1] == 0) and (i == 0 or me[i - 1] == 0):
            unprovoked_d_runs += 1

    if opp_rate > 0.8:
        allow = 5
    elif opp_rate > 0.65:
        allow = 4
    elif opp_rate > 0.45:
        allow = 3
    elif opp_rate > 0.25:
        allow = 2
    else:
        allow = 0

    if unprovoked_d_runs >= 2:
        allow = min(allow, 1)
    if recent_cd >= 6:
        allow = 0
    if recent_op_c < 2 and opp_rate < 0.5:
        allow = 0

    if n == 99:
        return 'D'

    if last_op == 1:
        if run_op_d <= allow and our_c_in_run >= run_op_d and opp_rate >= 0.18:
            return 'C'

        if last_me == 1:
            if (run_me_d >= 2 and opp_rate > 0.45 and recent_cd <= 5 and
                    unprovoked_d_runs <= 2 and dc_streak == 0):
                return 'C'
            if run_me_d >= 3 and opp_rate > 0.25 and recent_cd <= 4 and unprovoked_d_runs <= 3:
                return 'C'

        if run_op_d <= 2 and opp_rate > 0.8 and recent_cd <= 2 and unprovoked_d_runs <= 1:
            return 'C'

        return 'D'

    if last_me == 1:
        if n >= 97 and dc_streak <= 1 and resp_myD_c == 0 and opp_rate <= 0.95:
            return 'C'

        if dc_streak >= 2 and opp_rate > 0.55 and resp_myD_c >= resp_myD_d:
            return 'D'

        if opp_rate > 0.6 and resp_myD_d == 0 and dc_streak >= 1:
            if n < 95 or opp_rate > 0.8:
                return 'D'

        if opp_rate > 0.7 and recent_cd <= 4 and resp_myD_c > resp_myD_d:
            return 'D'

        if recent_dc >= 2 and opp_rate > 0.55 and resp_myD_d == 0:
            return 'D'

        return 'C'

    pre_run_d = 0
    pre_our_c = 0
    j = n - run_op_c - 1
    while j >= 0 and op[j] == 1:
        pre_run_d += 1
        if me[j] == 0:
            pre_our_c += 1
        j -= 1

    if (pre_run_d >= 4 and pre_our_c == pre_run_d and run_op_c <= 2 and
            opp_rate > 0.55 and unprovoked_d_runs <= 1 and recent_cd <= 6 and
            resp_myD_d == 0 and dc_streak == 0 and n <= 95):
        return 'D'

    if (cc_streak >= 8 and opp_rate > 0.85 and unprovoked_d_runs == 0 and
            recent_cd == 0 and n > 65 and n < 90):
        if rng.random() < 0.05:
            return 'D'

    if (recent_op_c >= 6 and opp_rate > 0.65 and recent_cd <= 1 and
            resp_myD_d == 0 and n < 90):
        if rng.random() < 0.025:
            return 'D'

    return 'C'
